pub fn squash(v: &mut Vec<String>) {
    // ASCII whitespace check for a single byte (U+0009..U+000D, U+0020)
    let is_ws = |b: u8| matches!(b, b'\t' | b'\n' | b'\x0B' | b'\x0C' | b'\r' | b' ');
    let trim = |s: &str| -> &str {
        let b = s.as_bytes();
        let mut start = 0;
        let mut end = b.len();
        while start < end && is_ws(b[start]) {
            start += 1;
        }
        while end > start && is_ws(b[end - 1]) {
            end -= 1;
        }
        // safe: boundaries are only at ASCII whitespace positions
        &s[start..end]
    };

    // Remove consecutive duplicates in place, comparing ORIGINAL values.
    // Invariant: slot `write - 1` holds the original of the last kept run.
    let mut write = 1usize;
    for read in 1..v.len() {
        if v[read] != v[write - 1] {
            v.swap(write, read);
            write += 1;
        }
    }
    v.truncate(write);

    // Trim AFTER dedup, on every surviving string.
    for s in v.iter_mut() {
        *s = trim(s).to_string();
    }
}
