use std::collections::{HashMap, VecDeque};
use std::hash::Hash;

pub struct Lru<K, V> {
    cap: usize,
    map: HashMap<K, V>,
    order: VecDeque<K>, // front = most recently used, back = least recently used
}

impl<K, V> Lru<K, V>
where
    K: Eq + Hash + Clone,
{
    pub fn new(cap: usize) -> Self {
        assert!(cap >= 1, "capacity must be at least 1");
        Self {
            cap,
            map: HashMap::new(),
            order: VecDeque::new(),
        }
    }

    pub fn put(&mut self, k: K, v: V) {
        if self.map.contains_key(&k) {
            self.map.insert(k.clone(), v);
            self.move_to_front(&k);
            return;
        }
        if self.order.len() == self.cap {
            let lru = self
                .order
                .pop_back()
                .expect("order is non-empty when at capacity");
            self.map.remove(&lru);
        }
        self.map.insert(k.clone(), v);
        self.order.push_front(k);
    }

    pub fn get(&mut self, k: &K) -> Option<&V> {
        if self.map.contains_key(k) {
            self.move_to_front(k);
            self.map.get(k)
        } else {
            None
        }
    }

    fn move_to_front(&mut self, k: &K) {
        if let Some(pos) = self.order.iter().position(|x| x == k) {
            let v = self
                .order
                .remove(pos)
                .expect("position is valid");
            self.order.push_front(v);
        }
    }
}
