use std::sync::Arc;
use std::thread;

pub fn parallel_map<T, R, F>(items: Vec<T>, f: F, workers: usize) -> Vec<R>
where
    T: Send + 'static,
    R: Send + 'static,
    F: Fn(T) -> R + Send + Sync + 'static,
{
    let n = items.len();
    let base = n / workers;
    let rem = n % workers;

    // Split into `workers` contiguous chunks (first `rem` chunks get one extra
    // element), moving each element exactly once.
    let mut rest = items;
    let mut pieces: Vec<Vec<T>> = Vec::with_capacity(workers);
    for i in (0..workers).rev() {
        let len = base + if i < rem { 1 } else { 0 };
        let piece = if len == rest.len() {
            std::mem::take(&mut rest)
        } else {
            rest.split_off(rest.len() - len)
        };
        pieces.push(piece);
    }
    pieces.reverse();

    // Share the closure across exactly `workers` threads.
    let f = Arc::new(f);
    let mut handles: Vec<thread::JoinHandle<Vec<R>>> = Vec::with_capacity(workers);
    for piece in pieces {
        let f = Arc::clone(&f);
        handles.push(thread::spawn(move || piece.into_iter().map(|x| f(x)).collect()));
    }

    // Collect in chunk order, which equals the original input order.
    let mut out: Vec<R> = Vec::with_capacity(n);
    for handle in handles {
        out.extend(handle.join().expect("parallel_map worker thread panicked"));
    }
    out
}
