use std::marker::PhantomData;

/// An iterator over non-overlapping consecutive mutable pairs of a slice.
///
/// For a slice of length `n`, yields `n / 2` pairs `(s[0..2], s[2..4], ...)`
/// and drops a single trailing element when `n` is odd.
///
/// Soundness: the backing pointer is advanced exactly two elements per call,
/// and each `next` borrows only the two elements at the current window that
/// have not been (and will not be) handed out again. No two live references
/// ever alias each other, and no element is ever yielded more than once.
pub struct PairsMut<'a, T> {
    ptr: *mut T,
    len: usize,
    _marker: PhantomData<&'a mut T>,
}

/// Splits `s` into an iterator of non-overlapping consecutive `(&mut T, &mut T)`
/// pairs. The odd trailing element, if any, is not yielded.
pub fn pairs_mut<'a, T>(s: &mut [T]) -> PairsMut<'a, T> {
    PairsMut {
        ptr: s.as_mut_ptr(),
        len: s.len(),
        _marker: PhantomData,
    }
}

impl<'a, T: 'a> Iterator for PairsMut<'a, T> {
    type Item = (&'a mut T, &'a mut T);

    fn next(&mut self) -> Option<Self::Item> {
        if self.len < 2 {
            self.len = 0;
            None
        } else {
            let ptr = self.ptr;
            unsafe {
                // Invariant: `ptr` points into the original slice and at most
                // `len` elements remain at or after it. The window
                // [ptr, ptr + 2) is a subset of the slice, was never handed
                // out before (ptr only ever moves forward in steps of 2), and
                // is disjoint from any previously created pair. Creating the
                // two disjoint &mut references is therefore sound.
                self.ptr = ptr.add(2);
                self.len -= 2;
                Some((&mut *ptr, &mut *ptr.add(1)))
            }
        }
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let n = self.len / 2;
        (n, Some(n))
    }
}
