use std::future::Future;
use std::pin::Pin;
use std::sync::Arc;
use std::task::{Context, Poll, Wake, Waker};
use std::thread;

/// A waker that unparks the thread blocked in `block_on`.
struct ThreadWaker {
    target: thread::Thread,
}

impl Wake for ThreadWaker {
    fn wake(self: Arc<Self>) {
        self.wake_by_ref()
    }
    fn wake_by_ref(self: &Arc<Self>) {
        self.target.unpark();
    }
}

/// Runs a future to completion on the current thread.
///
/// While the future is Pending, this thread parks and is only re-polled after
/// the future's waker fires (e.g. `wake()` from another thread) — no
/// busy-spinning. A wake that arrives before `park()` is recorded as a
/// permit, so `park()` returns immediately and no wakeup is lost.
pub fn block_on<F: Future>(fut: F) -> F::Output {
    let waker = Waker::from(Arc::new(ThreadWaker {
        target: thread::current(),
    }));
    let mut cx = Context::from_waker(&waker);
    let mut fut = fut;
    // SAFETY: `fut` lives on this stack and is never moved again; all
    // accesses go through the returned `Pin`.
    let mut fut = unsafe { Pin::new_unchecked(&mut fut) };

    loop {
        match fut.as_mut().poll(&mut cx) {
            Poll::Ready(value) => return value,
            Poll::Pending => thread::park(),
        }
    }
}

/// A future that yields: each poll with `remaining > 0` decrements it,
/// wakes the context's waker (by ref) and returns Pending; once
/// `remaining == 0` the next poll resolves with `Ready(())`.
pub struct YieldNow {
    pub remaining: u32,
}

impl Future for YieldNow {
    type Output = ();

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        let mut this = self.as_mut();
        if this.remaining > 0 {
            this.remaining -= 1;
            cx.waker().wake_by_ref();
            Poll::Pending
        } else {
            Poll::Ready(())
        }
    }
}
